                        if(cn[3]&&In(u1,v2))q[++r]=3,cg(v2,u1);
                    default:break;
                }
            }ans=0;
            for(ODT it:st)
                if(it.d)ans+=sf[it.r]-sf[it.l-1];
            printf("%d\n",ans);
        }
        return 0;
    }
